import{_ as o,l as r,o as e,c as n,v as t,p as s,x as l,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"长文档上采样","description":"","frontmatter":{"title":"长文档上采样","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/long-doc-upsampling.md","filePath":"llm/long-doc-upsampling.md","lastUpdated":1789023840000}'),m={name:"llm/long-doc-upsampling.md"};function E(c,a,A,f,u,_){const i=r("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="长文档上采样" tabindex="-1">长文档上采样 <a class="header-anchor" href="#长文档上采样" aria-label="Permalink to &quot;长文档上采样&quot;">​</a></h1><div class="epigraph"><p>随机打包会把短网页填满窗口，模型很少在预训练里见到接近上下文上限的连贯文档；要长上下文，先要在数据里真的出现长序列。</p><footer>—— 据 Xiong 等对基础模型长上下文扩展、Fu 等对 128K 数据工程的讨论整理</footer></div><p><a href="/llm/fim-training">上一课</a>改了条件方向，窗口长度仍由打包说了算。网页为主的混合物里，多数文档远短于 8k 或 128k，朴素拼接会得到「许多短篇拼成的假长上下文」：注意力看见的是文档缝，不是篇章依赖。本课不重讲 FIM 哨兵。缺口是长度分布：如何上采样真正的长文档，并减少跨文档注意力的误导，为后面的指令进预训练与退火留出「已经见过长跨度」的底座。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/llm/data-mixture-laws">配比定律</a> 的桶通常按来源，不按长度。书籍、论文、仓库超文档是长跨度的主要来源，但 token 份额可能很小。Xiong 等人在扩展 Llama 2 上下文时强调，继续预训练的数据必须含长序列；Fu 等人把 128K 的数据工程写成可操作的过滤与采样。缺的是与现有配比栈的接口：α、仓库排布、FIM 都改变了「一条训练样本长什么样」，长度必须作为独立轴，否则长窗口只在微调阶段突然出现，位置编码外推会脆。</p><p>另一面是浪费：把所有短文档丢掉只训书，覆盖崩掉。上采样不是删除短文档，而是提高长文档被抽到的概率，或在打包时优先把长文档放进完整窗口、短文档去填剩余。</p><h3 id="假长与真长" tabindex="-1">假长与真长 <a class="header-anchor" href="#假长与真长" aria-label="Permalink to &quot;假长与真长&quot;">​</a></h3><p>拼接短文档得到长度 \\(L\\) 的序列，对计算是长的，对语义是许多条短依赖。评测若用针在稻草堆里找事实，模型可以利用「文档边界特殊 token」作弊，也可以彻底失败。训练日志应分别报：单文档跨度的分位数、以及打包后的序列长度。只报后者会假装已经在做长上下文。</p><p><span class="marginnote">清洗规则若丢掉没有终结标点的行，书籍与列表会被误杀，长文档来源先枯竭。长度轴要与网页启发式解耦。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>为每条文档记录 token 长度（用冻结词表）。设阈值 \\(L_{\\mathrm{long}}\\)（与目标窗口同量级或为其分数）。对超过阈值的文档赋予更高的抽样权重，或单独开一个「长」桶，用人工 / DoReMi 给它非零 \\(w\\)。打包策略改为：先放一条长文档的连续切片（可重叠以覆盖中部），再用短文档填微批里的空洞；切片尽量不在句子中途切断。仓库超文档算长文档，但切片应尊重文件边界，以免假长。</p><p>继续预训练到更长窗口时，上采样比例通常再提高，短网页降权。这与后面退火课的「后期提高质量」可以共用时间表，但本课的自变量是长度不是质量标签。</p><h3 id="与-fertility-的交叉" tabindex="-1">与 fertility 的交叉 <a class="header-anchor" href="#与-fertility-的交叉" aria-label="Permalink to &quot;与 fertility 的交叉&quot;">​</a></h3><p>高 fertility 语言的「长」更容易达到阈值，只因切得碎。阈值应按字符或按句子，或按语言分位，否则 α 采样与长度采样会双重偏向碎语言的「假长」。</p><p><span class="marginnote">FIM 在长切片上挖中间，编辑任务更真实，也更贵。应设上限，避免每个长窗口都做重排。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>位置编码与注意力只有在训练分布里见过较大的相对距离，才会对大距离给出稳定的分数。数据里若最大真跨度远小于窗口，多出来的位置是外推。上采样把真跨度的支撑往右推。它不改变 SDPA 的二次代价——那是并行课的序列并行要付的账——只改变优化看到的距离分布。</p>',17)),(e(),s(h,null,{default:l(()=>[p(i,{id:"mermaid-49",class:"mermaid",graph:"flowchart%20TD%0A%20%20LEN%5B%22%E6%8C%89%E8%AF%8D%E8%A1%A8%E8%AE%A1%E9%87%8F%E9%95%BF%E5%BA%A6%22%5D%20--%3E%20SPLIT%7B%22%E8%B6%85%E8%BF%87%E9%95%BF%E9%98%88%E5%80%BC%3F%22%7D%0A%20%20SPLIT%20--%3E%7C%22%E6%98%AF%22%7C%20UP%5B%22%E6%8F%90%E9%AB%98%E6%8A%BD%E6%A0%B7%E6%9D%83%E9%87%8D%22%5D%0A%20%20SPLIT%20--%3E%7C%22%E5%90%A6%22%7C%20SHORT%5B%22%E7%9F%AD%E6%96%87%E6%A1%A3%E5%A1%AB%E7%BC%9D%22%5D%0A%20%20UP%20--%3E%20PACK%5B%22%E8%BF%9E%E7%BB%AD%E5%88%87%E7%89%87%E8%BF%9B%E6%BB%A1%E7%AA%97%22%5D%0A%20%20SHORT%20--%3E%20PACK%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>上采样救不了词表对长数字、长代码行的碎切；窗口会被 fertility 吃掉。也不等于检索：超长书仍可能要 RAG，那是另一门课。下一课把「已经能看长」的序列里掺进指令格式，让协议 token 在预训练里就不是 glitch。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>本课不重讲 FIM；只补真长跨度在混合物里太稀。</li><li>按长度加权重或单独开长桶，打包时连续切片，短文档只填缝。</li><li>区分打包长度与单文档跨度；阈值要防 fertility 造假长。</li><li>为窗口扩展提供训练支撑，不降低注意力的计算复杂度。</li><li>出处：Xiong et al., <em>Effective Long-Context Scaling of Foundation Models</em>；Fu et al., 128K 数据工程；书籍来源对照 Gao et al., The Pile。</li></ul>',4))])}const g=o(m,[["render",E]]);export{P as __pageData,g as default};
